function publicHttpAddress(host:string):boolean {if(!/^\d{1,3}(\.\d{1,3}){3}$/.test(host))return false;const [a,b,c,d]=host.split(".").map(Number);if([a,b,c,d].some(part=>part>255))return false;return !(a===0||a===10||a===127||a>=224||(a===100&&b>=64&&b<=127)||(a===169&&b===254)||(a===172&&b>=16&&b<=31)||(a===192&&(b===168||b===0||(b===88&&c===99)))||(a===198&&(b===18||b===19||(b===51&&c===100)))||(a===203&&b===0&&c===113));}
function safeRouterUrl(value:string,allowedHttpOrigins:string[]=[]):string {try{if(!value.trim())return "";const url=new URL(value.trim());const host=url.hostname.toLowerCase();const approvedHttp=url.protocol==="http:"&&allowedHttpOrigins.includes(url.origin)&&publicHttpAddress(host);const publicHttps=url.protocol==="https:"&&host.includes(".")&&!host.endsWith(".local")&&!host.endsWith(".localhost")&&host!=="localhost"&&!host.includes(":")&&!/^\d+\./.test(host);if((!approvedHttp&&!publicHttps)||url.username||url.password||url.search||url.hash||!(url.pathname.replace(/\/+$/,"")||"/v1").endsWith("/v1"))return "";url.pathname=url.pathname.replace(/\/+$/,"")||"/v1";return url.toString().replace(/\/$/,"");}catch{return "";}}
function safeRouterSettings(value:unknown,allowedHttpOrigins:string[]=[]):RouterConfig {const item=value&&typeof value==="object"?value as Record<string,unknown>:{};const text=(key:string,max=256)=>typeof item[key]==="string"?String(item[key]).replace(/[\u0000-\u001f\u007f]/g,"").trim().slice(0,max):"";return{baseUrl:safeRouterUrl(text("baseUrl",2048),allowedHttpOrigins),textModel:text("textModel"),imageModel:text("imageModel"),audioModel:text("audioModel"),voice:text("voice",128)};}
