function saveLocal(key: string, value: unknown) { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* Device settings remain available in memory. */ } }
function removeLocal(key: string) { try { localStorage.removeItem(key); } catch {} }
function stored<T>(key: string, fallback: T): T { try { return JSON.parse(localStorage.getItem(key) || "null") ?? fallback; } catch { return fallback; } }
function defaultValues(feature: Feature): Values { return Object.fromEntries(feature.fields.filter(f => f.type !== "file").map(f => [f.id, f.defaultValue ?? (f.options?.[0]?.value || "")])); }
function readFile(file: File): Promise<string> { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Foto tidak dapat dibaca.")); reader.readAsDataURL(file); }); }
function loadImage(src: string): Promise<HTMLImageElement> { return new Promise((resolve, reject) => { const image = new window.Image(); image.onload = () => resolve(image); image.onerror = () => reject(new Error("Format gambar tidak didukung browser. Gunakan JPG, PNG, atau WEBP.")); image.src = src; }); }

function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  const closeRef = useRef(onClose);useEffect(()=>{closeRef.current=onClose;},[onClose]);
  useEffect(() => { const before = document.activeElement as HTMLElement; const oldOverflow = document.body.style.overflow; document.body.style.overflow = "hidden"; ref.current?.focus(); const handler = (e: KeyboardEvent) => { if (e.key === "Escape") closeRef.current(); if (e.key === "Tab") { const controls = ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]'); if (!controls?.length) return; const first = controls[0], last = controls[controls.length - 1]; if (e.shiftKey && (document.activeElement === first || document.activeElement === ref.current)) { e.preventDefault(); last.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); } } }; document.addEventListener("keydown", handler); return () => { document.body.style.overflow = oldOverflow; document.removeEventListener("keydown", handler); before?.focus(); }; }, []);
  return <div className="modal-scrim" onClick={onClose}><div className={`modal-card ${wide ? "modal-wide" : ""}`} ref={ref} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} onClick={e => e.stopPropagation()}><div className="modal-heading"><h2><BrandText text={title} /></h2><button className="icon-button" aria-label="Tutup / Close" onClick={onClose}><X size={20} /></button></div>{children}</div></div>;
}

