  function downloadLocal(result:Result){try{const anchor=document.createElement("a");let objectUrl="";if(result.text!==undefined){objectUrl=URL.createObjectURL(new Blob([result.text],{type:"text/plain;charset=utf-8"}));anchor.href=objectUrl;}else if(result.url?.startsWith("data:image/")){anchor.href=result.url;}else{throw new Error("File unduhan tidak tersedia. Buka kembali hasil dari Riwayat Kreasi.");}anchor.download=downloadFilename(result.id,result.text!==undefined?"text/plain":result.mimeType);document.body.appendChild(anchor);anchor.click();anchor.remove();if(objectUrl)window.setTimeout(()=>URL.revokeObjectURL(objectUrl),60_000);}catch(error){setError((error as Error).message,"download_failed");}}
  function downloadLink(result:Result,wide=false){if(activeId===ANGLE_GENERATOR_ID&&result.kind==="image")return <div className="angle-download-actions">{(["png","jpeg"] as const).map(format=><button key={format} type="button" className="secondary-button" onClick={()=>void exportAngleImage(result.url||"",result.angleId||result.id,result.angleRatio,format).catch(error=>setError((error as Error).message,"download_failed"))} aria-label={`${t("Unduh","Download")} ${format==="jpeg"?"JPG":"PNG"}`}><Download size={14}/>{format==="jpeg"?"JPG":"PNG"}</button>)}</div>;const href=serverDownloadUrl(result.url);const className=wide?"primary-button full-button":"icon-button";const label=wide?t("Unduh Gambar","Download Image"):t("Unduh hasil","Download result");return href?<a className={className} href={href} download={downloadFilename(result.id,result.mimeType)} aria-label={label} title={label}><Download size={wide?18:18}/>{wide&&label}</a>:<button type="button" className={className} aria-label={label} title={label} onClick={()=>downloadLocal(result)}><Download size={18}/>{wide&&label}</button>;}
  async function copy(text: string) { try { await navigator.clipboard.writeText(text); setNotice(t("Teks berhasil disalin", "Text copied")); } catch { setError(t("Clipboard tidak tersedia. Pilih lalu salin teks secara manual.", "Clipboard is unavailable. Select and copy the text manually.")); } }
