  function navItem(feature: Feature, favorite = false) { return <div className={`nav-item ${parentFeature.id === feature.id ? "selected" : ""} ${feature.id === "beranda" ? "nav-home" : ""}`} key={`${favorite ? "fav-" : ""}${feature.id}`}><button className="nav-feature" onClick={() => navigate(feature.id)} disabled={working} aria-current={parentFeature.id === feature.id ? "page" : undefined}><FeatureIcon id={feature.id} size={24} /><span>{translated(feature.label.replace(/\s*NEW$/, ""))}</span>{feature.isNew && <b className="new-badge">NEW</b>}</button>{feature.id !== "beranda" && <button className={`favorite-button ${favorites.includes(feature.id) ? "is-favorite" : ""}`} aria-label={`${favorites.includes(feature.id) ? t("Hapus favorit", "Remove favorite") : t("Tambah favorit", "Add favorite")}: ${feature.label}`} onClick={() => toggleFavorite(feature.id)}><Star size={14} fill={favorites.includes(feature.id) ? "currentColor" : "none"} /></button>}</div>; }
  function fieldControl(field: FeatureField) { if(activeId===ANGLE_GENERATOR_ID&&["angle-ids","angle-expression"].includes(field.id))return <AngleGeneratorControls key={field.id} fieldId={field.id} value={String(activeValues[field.id]??"")} disabled={working} language={lang} onChange={value=>setValues(previous=>({...previous,[field.id]:value}))}/>; const value = activeValues[field.id] ?? ""; const change = (v:string|number) => {const target=variantTarget(active,field.id,v);if(target&&allFeatures.some(f=>f.id===target)){navigate(target);return;}setValues(previous=>({...previous,[field.id]:v}));}; return <div className={`form-field ${field.type === "textarea" ? "field-full" : ""}`} key={field.id}><label htmlFor={`field-${field.id}`}>{field.label}{field.required && <span className="required"> *</span>}</label>{field.type === "textarea" ? <textarea id={`field-${field.id}`} rows={4} value={String(value)} onChange={e => change(e.target.value)} placeholder={field.placeholder || field.help || t("Tuliskan detail yang kamu inginkan…", "Describe what you have in mind…")} required={field.required} /> : field.type === "select" ? <select id={`field-${field.id}`} value={String(value)} onChange={e => change(e.target.value)}>{field.options?.map(option => <option key={option.value} value={option.value} disabled={selectedProvider==="9router"&&outputKind==="image"&&(field.role==="ratio"||field.role==="aspectRatio")&&routerImageSizeStrategy(effectiveRouter.imageModel)==="mapped-ratio"&&!(routerMappedAspectRatios as readonly string[]).includes(option.value)}>{option.label}</option>)}</select> : field.type === "choice" ? <div className="choice-group" id={`field-${field.id}`} tabIndex={-1} role="group" aria-label={field.label}>{field.options?.map(option => <button key={option.value} type="button" className={`choice ${String(value) === option.value ? "chosen" : ""}`} aria-pressed={String(value) === option.value} disabled={selectedProvider==="9router"&&outputKind==="image"&&(field.role==="ratio"||field.role==="aspectRatio")&&routerImageSizeStrategy(effectiveRouter.imageModel)==="mapped-ratio"&&!(routerMappedAspectRatios as readonly string[]).includes(option.value)} onClick={() => change(option.value)}>{option.label}</button>)}</div> : field.type === "range" ? <div className="range-field"><input id={`field-${field.id}`} type="range" min={field.min ?? 0} max={field.max ?? 100} step={field.step ?? 1} value={Number(value)} onChange={e => change(Number(e.target.value))} /><output>{String(value)}</output></div> : <input id={`field-${field.id}`} type={field.type === "number" || field.type === "color" ? field.type : "text"} min={field.min} max={field.max} value={String(value)} onChange={e => change(field.type === "number" ? Number(e.target.value) : e.target.value)} required={field.required} placeholder={field.placeholder || field.help || ""} />}{field.help && <small>{field.help}</small>}</div>; }
  function uploadArea(fieldId: string, title: string, multiple = true) { const current = uploads.filter(u => u.fieldId === fieldId); const uploadField=activeFields.find(f=>f.id===fieldId);const isVideo=uploadField?.role==="video"; return <div className="upload-field" key={fieldId}><label className="upload-title" htmlFor={`upload-${fieldId}`}>{title}{uploadField?.required&&<span className="required"> *</span>}</label><label className={`upload-drop ${current.length ? "upload-compact" : ""}`} htmlFor={`upload-${fieldId}`} onDragOver={e => { e.preventDefault(); }} onDrop={e => { e.preventDefault(); addFiles(e.dataTransfer.files, fieldId, multiple); }}><span className="upload-symbol"><UploadCloud size={28} /></span><strong>{current.length ? t("Ganti foto", "Replace photo") : isVideo?t("Klik atau seret video ke sini", "Click or drop your video here"):t("Klik atau seret foto ke sini", "Click or drop your photo here")}</strong><span id={`upload-help-${fieldId}`}>{isVideo?"MP4, MOV, WEBM · 200 MB":"PNG, JPG, WEBP · 25 MB"}</span><input id={`upload-${fieldId}`} className="upload-file-input" aria-label={title} aria-describedby={`upload-help-${fieldId}`} type="file" accept={isVideo?"video/mp4,video/webm,video/quicktime":"image/png,image/jpeg,image/webp"} multiple={multiple} aria-required={uploadField?.required} disabled={working} onChange={e=>{const selected=Array.from(e.currentTarget.files||[]);e.currentTarget.value="";if(selected.length)addFiles(selected,fieldId,multiple);}} /></label>{current.length > 0 && <div className="upload-thumbnails">{current.map(u => <div key={u.id} className="upload-thumb"><img src={`data:${u.mimeType};base64,${u.data}`} alt={u.name} /><span title={u.name}>{u.name}</span><button type="button" aria-label={`${t("Hapus", "Remove")} ${u.name}`} disabled={working} onClick={() => removeUpload(u.id)}><X size={14} /></button></div>)}</div>}</div>; }
  function errorPanel() { const action=recoveryAction(errorCode);return error && <div className="error-panel" role="alert"><Info size={20} /><div><strong>{t("Permintaan belum berhasil", "Request could not be completed")}</strong><p>{error}</p>{errorRequestId&&<small>{t("ID permintaan", "Request ID")}: {errorRequestId}</small>}{action==="settings"?<button type="button" className="text-button" onClick={()=>setDialog("settings")}>{t("Buka pengaturan AI", "Open AI settings")} <ArrowRight size={14}/></button>:action==="history"?<button type="button" className="text-button" onClick={openHistory}>{t("Periksa Riwayat Kreasi", "Check Creation History")} <History size={14}/></button>:action==="signin"&&<a className="text-button" href={session?.signInUrl||"/signin-with-chatgpt?return_to=%2F"}>{t("Masuk kembali", "Sign in again")} <ArrowRight size={14}/></a>}</div><button type="button" className="icon-button" aria-label={t("Tutup pesan", "Dismiss error")} onClick={()=>setError("")}><X size={16}/></button></div>; }
  function resultCards(items: Result[]) { return <div className="results-grid">{items.map((result, index) => <article className={`result-card ${result.kind === "text" ? "result-text" : ""}`} key={result.id}>{result.kind === "image" && result.url ? <button className="result-image-button" onClick={() => setPreview(result)} aria-label={t("Lihat gambar ukuran penuh", "View full size image")}><img src={result.url} alt={`${active.label} — ${t("hasil", "result")} ${index + 1}`} loading="lazy" /><span><Expand size={18} /></span></button> : result.kind === "audio" && result.url ? <AudioPlayer url={result.url} lang={lang} /> : <div className="text-result-content">{result.text}</div>}{result.warnings?.length?<div className="result-warning"><Info size={14}/><p>{result.warnings.join(" ")}</p></div>:null}<div className="result-card-actions"><span>{result.angleId ? (lang==="en"?ANGLE_DEFINITIONS.find(angle=>angle.id===result.angleId)?.labelEn:ANGLE_DEFINITIONS.find(angle=>angle.id===result.angleId)?.labelId) : result.kind === "image" ? t("Foto", "Image") : result.kind === "audio" ? "Audio" : t("Teks", "Text")} {!result.angleId&&index + 1}</span><div>{result.text && <button className="icon-button" title={t("Salin", "Copy")} onClick={() => copy(result.text!)}><Copy size={17} /></button>}{downloadLink(result)}<button className="icon-button" title={t("Hapus dari layar", "Remove from view")} onClick={() => setResultsByFeature(p => ({ ...p, [activeId]: (p[activeId] || []).filter(r => r.id !== result.id) }))}><Trash2 size={16} /></button></div></div></article>)}</div>; }

